args.query:
PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?substation ?substationName WHERE {
  ?substation a cim:Substation ;
              cim:IdentifiedObject.name ?substationName .

  ?substation cim:Substation.VoltageLevels ?voltageLevel .
  ?voltageLevel cim:VoltageLevel.Bays ?bay .
  ?bay cim:Bay.Equipments ?equipment .

  VALUES ?equipmentIRI { <urn:uuid:681a3087-5a55-11eb-a658-74e5f963e191> }
  ?equipment rdf:type ?equipmentType .
  FILTER(?equipment = ?equipmentIRI)
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?equipment ?equipmentName ?equipmentType WHERE {
  VALUES ?equipmentIRI { <urn:uuid:681a3087-5a55-11eb-a658-74e5f963e191> }
  ?equipment rdf:type ?equipmentType .
  ?equipment cim:IdentifiedObject.name ?equipmentName .
  FILTER(?equipment = ?equipmentIRI)
}

