args.query:
PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX eu: <https://cim.ucaiug.io/ns/eu#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?busbarSection ?busbarSectionName ?substation ?substationName WHERE {
  ?busbarSection rdf:type cim:BusbarSection ;
                cim:IdentifiedObject.name ?busbarSectionName .

  OPTIONAL {
    ?substation cim:Substation.VoltageLevels ?voltageLevel .
    ?voltageLevel cim:VoltageLevel.Bays ?bay .
    ?bay cim:Bay.VoltageLevel ?voltageLevel .
    ?busbarSection cim:Equipment.EquipmentContainer ?bay .
    ?substation cim:IdentifiedObject.name ?substationName .
  }

  FILTER(?busbarSectionName = "FEDA    300 A")
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?busbarSection ?busbarSectionName ?equipmentContainer WHERE {
  ?busbarSection rdf:type cim:BusbarSection ;
                cim:IdentifiedObject.name ?busbarSectionName .

  ?busbarSection cim:Equipment.EquipmentContainer ?equipmentContainer .

  FILTER(?busbarSectionName = "FEDA    300 A")
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?containerType ?containerName WHERE {
  ?equipmentContainer rdf:type ?containerType ;
                     cim:IdentifiedObject.name ?containerName .

  FILTER(?equipmentContainer = <urn:uuid:f176967e-9aeb-11e5-91da-b8763fd99c5f>)
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?substation ?substationName WHERE {
  ?voltageLevel rdf:type cim:VoltageLevel ;
                cim:IdentifiedObject.name "FEDA    300" .

  ?voltageLevel cim:VoltageLevel.Substation ?substation .
  ?substation cim:IdentifiedObject.name ?substationName .
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?switch ?switchName WHERE {
  ?switch rdf:type cim:LoadBreakSwitch .
  ?switch cim:IdentifiedObject.mRID "55de4e32-8cb0-4602-9901-ec91e104b300" .
  OPTIONAL { ?switch cim:IdentifiedObject.name ?switchName }
}

