SELECT ?voltageLevel WHERE {
  ?equipment rdf:type cim:Equipment .
  ?equipment cim:IdentifiedObject.mRID "62585c75-b020-614c-89a1-fec7c118c3fa" .
  ?equipment cim:Equipment.EquipmentContainer ?container .
  ?container rdf:type cim:EquipmentContainer .
  OPTIONAL {
    ?container cim:EquipmentContainer.Equipments ?equipmentInContainer .
    ?equipmentInContainer rdf:type cim:VoltageLevel .
    ?equipmentInContainer cim:IdentifiedObject.mRID ?voltageLevelId .
  }
  OPTIONAL {
    ?container cim:EquipmentContainer.Equipments ?equipmentInContainer .
    ?equipmentInContainer rdf:type cim:Bay .
    ?equipmentInContainer cim:Bay.VoltageLevel ?voltageLevel .
  }
  OPTIONAL {
    ?container rdf:type cim:VoltageLevel .
    ?container cim:IdentifiedObject.mRID ?voltageLevelId .
  }
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?voltageLevel ?voltageLevelId WHERE {
  ?equipment rdf:type cim:Equipment .
  ?equipment cim:IdentifiedObject.mRID "62585c75-b020-614c-89a1-fec7c118c3fa" .
  ?equipment cim:Equipment.EquipmentContainer ?container .

  # Find the voltage level in the container hierarchy
  {
    ?container rdf:type cim:VoltageLevel .
    ?container cim:IdentifiedObject.mRID ?voltageLevelId .
    BIND(?container AS ?voltageLevel)
  } UNION {
    ?container rdf:type cim:Bay .
    ?container cim:Bay.VoltageLevel ?voltageLevel .
    ?voltageLevel cim:IdentifiedObject.mRID ?voltageLevelId .
  } UNION {
    ?container rdf:type cim:Substation .
    ?container cim:Substation.VoltageLevels ?voltageLevel .
    ?voltageLevel cim:IdentifiedObject.mRID ?voltageLevelId .
  }
}

