args.query:
PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?diagramObject ?diagramObjectName WHERE {
  ?substation a cim:Substation .
  ?substation cim:IdentifiedObject.name "ARENDAL" .

  ?diagramObject a cim:DiagramObject .
  ?diagramObject cim:DiagramObject.IdentifiedObject ?substation .
  OPTIONAL { ?diagramObject cim:IdentifiedObject.name ?diagramObjectName }
} LIMIT 20

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?diagram WHERE {
  ?diagram rdf:type cim:Diagram .
  ?diagram cim:IdentifiedObject.mRID "7340e79a-9cff-4bb5-bddc-389e3358f71b" .
}

PREFIX cim: <https://cim.ucaiug.io/ns#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?diagramObject ?name WHERE {
  ?diagram rdf:type cim:Diagram .
  ?diagram cim:IdentifiedObject.mRID "7340e79a-9cff-4bb5-bddc-389e3358f71b" .

  ?diagramObject rdf:type cim:DiagramObject .
  ?diagramObject cim:DiagramObject.Diagram ?diagram .

  OPTIONAL { ?diagramObject cim:IdentifiedObject.name ?name }
}

